  p.getAttribute(BuiltInRegistries.ATTRIBUTE.get(Identifier.parse("spell_power:fire")).orElseThrow()).setBaseValue(40);p.addEffect(new MobEffectInstance(effect("skill_tree_rpgs:fire_ward"),120,5));check(p.getAbsorptionAmount()>0,"Fire Ward has native absorption");target=enemy(0,4);lines.add("Fire power="+SpellPower.getSpellPower(SpellSchools.FIRE,p)+" ward coefficient="+spell("skill_tree_rpgs:fire_tier_3_passive_2").value().impacts.getFirst().action.damage.spell_power_coefficient);p.hurtServer(w,p.damageSources().mobAttack(target),1);eq("Flameward retaliates on absorption-only hit",1000-target.getHealth(),6.4);float reflected=target.getHealth();p.invulnerableTime=0;p.hurtServer(w,p.damageSources().mobAttack(target),1);eq("Flameward beam repeat respects fixed half-second gate",target.getHealth(),reflected);target.discard();reset();
