  target=enemy(0,3);target.getAttribute(Attributes.ARMOR).setBaseValue(20);hit(target,"wizards:frost_lance");float base=1000-target.getHealth();target.setHealth(1000);target.removeAllEffects();equip(List.of(),List.of("skill_tree_rpgs:frost_tier_3_spell_2_modifier_1"));hit(target,"wizards:frost_lance");float penetrated=1000-target.getHealth();check(penetrated>base,"Colossal actual projectile hit ignores armor");eq("Colossal leaves actual armor unchanged",target.getArmorValue(),20);target.discard();reset();
  equip(List.of(),List.of("skill_tree_rpgs:arcane_tier_4_spell_1_modifier_2"));target=enemy(0,4);MageFollowup.burst(w,p,new Vec3(0,80,4),context("wizards:arcane_blink"));eq("Blitz native blast20% P",1000-target.getHealth(),6.4);target.discard();reset();
