  var fresh=new SpellCooldownManager(p);BlinkCharges.copy(manager,fresh,p);eq("Blitz saved head recovery",duration(fresh,BlinkCharges.HEAD),100);eq("Blitz saved serial tail recovery",duration(fresh,BlinkCharges.TAIL),340);set(fresh,Identifier.parse("wizards:fireball"),77);BlinkCharges.copy(manager,fresh,p);eq("Blitz copying preserves unrelated cooldown",duration(fresh,Identifier.parse("wizards:fireball")),77);manager.reset(null);reset();
