 void afterColdDamage(){check(cold.getHealth()<coldHP,"Native Frostbite actually damages without a custom DOT");check(FrostExposure.remaining(cold)>0,"Cold remains active before finite expiry");later(25,this::finish);}
 void finish(){check(FrostExposure.remaining(cold)==0,"Frostbite expires");check(cold.getTicksFrozen()<cold.getTicksRequiredToFreeze(),"Frostbite releases native threshold after expiry");cold.discard();write();}
 void abort(Throwable e){e.printStackTrace();check(false,"Runtime exception "+e);write();}
 void write(){try{Files.writeString(Path.of("phase-two-result.txt"),(failures==0?"PASS ":"FAIL ")+count+" checks; failures="+failures+"\n");Files.write(Path.of("phase-two-checks.txt"),lines);}catch(Exception e){e.printStackTrace();}server.halt(false);}
